def caesar_encrypt(plaintext, shift):
    ciphertext = ''
    for char in plaintext:
        if 'A' <= char <= 'Z':
            shifted = (ord(char) - 65 + shift) % 26 + 65
            ciphertext += chr(shifted)
        else:
            ciphertext += char  # keep non‑letters unchanged
    return ciphertext
